label.text:
model -> {
	period = ifElse(isEmpty($model),
		new(`tl.ai.monitor:Period`, transient: true)
			..set(`tl.ai.monitor:Period#preset`, 30),
		$model);
	#('Runs ({0})'@en, 'Läufe ({0})'@de)
		.fill($period.get(`tl.ai.monitor:Period#label`)).localize();
}

description.text:
model -> {
	period = ifElse(isEmpty($model),
		new(`tl.ai.monitor:Period`, transient: true)
			..set(`tl.ai.monitor:Period#preset`, 30),
		$model);
	executions = all(`tl.ai.execution:AgentExecution`);
	startedAt = e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`);
	start = $period.get(`tl.ai.monitor:Period#windowStart`);
	end = $period.get(`tl.ai.monitor:Period#windowEnd`);
	// A bound that is empty is dropped rather than tested. A period is normally a closed day
	// range with both ends filled - even "Alle", which reads them off the data - but one that
	// was never filled has no edges, and then it selects everything.
	recent = $executions.filter(e -> (isEmpty($start) || $startedAt($e) >= $start)
		&& (isEmpty($end) || $startedAt($e) < $end));
	children = $recent.filter(e -> !isEmpty($e.get(`tl.ai.execution:AgentExecution#parentExecution`))).size();
	{{{
		<div class="aiKpi">
			<div class="aiKpiValue">{numberFormat('#,##0').format($recent.size())}</div>
			<div class="aiKpiNote">
				{#('{0} of them sub-agents'@en, 'davon {0} Teilagenten'@de).fill($children)}
			</div>
		</div>
	}}};
}

modelBuilder.elements:
model -> {
	period = ifElse(isEmpty($model),
		new(`tl.ai.monitor:Period`, transient: true)
			..set(`tl.ai.monitor:Period#preset`, 30),
		$model);
	executions = all(`tl.ai.execution:AgentExecution`);
	startedAt = e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`);
	start = $period.get(`tl.ai.monitor:Period#windowStart`);
	end = $period.get(`tl.ai.monitor:Period#windowEnd`);
	// A bound that is empty is dropped rather than tested. A period is normally a closed day
	// range with both ends filled - even "Alle", which reads them off the data - but one that
	// was never filled has no edges, and then it selects everything.
	recent = $executions.filter(e -> (isEmpty($start) || $startedAt($e) >= $start)
		&& (isEmpty($end) || $startedAt($e) < $end));
	$recent;
}
